//! 🧪️ Shared render demand cases include large capacity and independent refusal currencies.
use super::*;
#[test]fn neutral_original_render_quotes(){let rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in rows["cases"].as_array().unwrap(){let d=&row["demand"];let demand=RetirementDemand{copy_bytes:d["copyBytes"].as_u64().unwrap()as usize,capacity_bytes:d["capacityBytes"].as_u64().unwrap()as usize,release_bytes:d["releaseBytes"].as_u64().unwrap()as usize,depth:d["depth"].as_u64().unwrap()as usize};let grant=|g:&serde_json::Value|RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize};let actual=match render_readiness(demand,grant(&row["remaining"]),grant(&row["total"]),row["cancelled"].as_bool().unwrap_or(false)){RenderReadiness::Enter=>"enter",RenderReadiness::Pending=>"pending",RenderReadiness::Refused=>"refused",RenderReadiness::Cancelled=>"cancelled"};assert_eq!(actual,row["expected"].as_str().unwrap(),"{}",row["name"]);}}
